WITH UserReputation AS (SELECT u.Id AS UserId, u.DisplayName, u.Reputation, RANK() OVER (ORDER BY u.Reputation DESC NULLS FIRST) AS ReputationRank FROM Users AS u), PostStats AS (SELECT p.OwnerUserId, COUNT(CASE WHEN p.PostTypeId = 1 THEN 1 END) AS QuestionsCount, COUNT(CASE WHEN p.PostTypeId = 2 THEN 1 END) AS AnswersCount, AVG(p.Score) AS AverageScore FROM Posts AS p GROUP BY p.OwnerUserId), CloseReasonSummary AS (SELECT ph.UserId, COUNT(*) AS CloseCount, GROUP_CONCAT(CASE WHEN NOT (ph.Comment IS NULL) THEN ph.Comment ELSE 'No comment' END, ', ') AS CloseComments FROM PostHistory AS ph WHERE ph.PostHistoryTypeId = 10 GROUP BY ph.UserId), CommentSummary AS (SELECT c.UserId, COUNT(c.Id) AS CommentsCount, SUM(CASE WHEN c.Score < 0 THEN 1 ELSE 0 END) AS NegativeCommentsCount FROM Comments AS c GROUP BY c.UserId) SELECT ur.UserId, ur.DisplayName, ur.Reputation, ur.ReputationRank, COALESCE(ps.QuestionsCount, 0) AS QuestionsCount, COALESCE(ps.AnswersCount, 0) AS AnswersCount, COALESCE(ps.AverageScore, 0) AS AverageScore, COALESCE(cr.CloseCount, 0) AS CloseCount, COALESCE(cr.CloseComments, 'No closures') AS CloseComments, COALESCE(cs.CommentsCount, 0) AS TotalComments, COALESCE(cs.NegativeCommentsCount, 0) AS NegativeComments FROM UserReputation AS ur LEFT JOIN PostStats AS ps ON ur.UserId = ps.OwnerUserId LEFT JOIN CloseReasonSummary AS cr ON ur.UserId = cr.UserId LEFT JOIN CommentSummary AS cs ON ur.UserId = cs.UserId WHERE ur.ReputationRank <= 100 ORDER BY ur.Reputation DESC NULLS FIRST, ur.DisplayName ASC